          code: "// 1101 序列检测器：Mealy 型状态机，允许重叠检测\n// 状态编码 S0=00, S1=01, S2=11, S3=10 与手算时的编码一致\nmodule seq_detect_1101(input clk, input rst_n, input x, output z);\n    localparam S0 = 2'b00, S1 = 2'b01, S2 = 2'b11, S3 = 2'b10;\n    reg [1:0] state, next;\n\n    // 第一段：状态寄存器（时序部分）\n    always @(posedge clk or negedge rst_n)\n        if (!rst_n) state <= S0;\n        else        state <= next;\n\n    // 第二段：次态与输出组合逻辑\n    always @(*) begin\n        next = S0;\n        case (state)\n            S0: next = x ? S1 : S0;\n            S1: next = x ? S2 : S0;\n            S2: next = x ? S2 : S3;\n            S3: next = x ? S1 : S0;   // 收到 1 表示检测到 1101，回到 S1 支持重叠\n            default: next = S0;\n        endcase\n    end\n\n    // Mealy 输出：处在 S3 且当前输入为 1 时输出一个脉冲\n    assign z = (state == S3) && x;\nendmodule\n\n// 模 6 同步加计数器：用 D 触发器方程直接描述\nmodule mod6_counter(input clk, input rst_n, output reg [2:0] q, output z);\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) q <= 3'b000;\n        else        q <= { (q[2] & ~q[0]) | (q[1] & q[0]),   // D2 = Q2Q0' + Q1Q0\n                           ~q[2] & (q[1] ^ q[0]),           // D1 = Q2'(Q1 ^ Q0)\n                           ~q[0] };                          // D0 = Q0'\n    end\n    assign z = q[2] & ~q[1] & q[0];   // 状态 101 时输出进位脉冲\nendmodule\n\n// 用集成计数器改接：模 6（初值 0000，计到 0101 时置数）\nmodule mod6_by_load(input clk, input rst_n, output [3:0] cnt, output tick);\n    reg [3:0] cnt_r;\n    wire load = (cnt_r == 4'd5);       // 0101 时产生同步置数信号\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n)     cnt_r <= 4'd0;\n        else if (load)  cnt_r <= 4'd0;  // 同步置数，无毛刺\n        else            cnt_r <= cnt_r + 4'd1;\n    end\n    assign cnt  = cnt_r;\n    assign tick = load;                // 每 6 个时钟输出一个脉冲\nendmodule"
